'use strict';
// Original explanations. Examples teach the idea without solving the exercises.
(() => {
const T=(ru,uk,en)=>[ru,uk,en];
const example=(code,lines,runs)=>({code,lines,runs});
const labels={
  pace:T('В своём темпе','У своєму темпі','At your own pace'),
  start:T('С нуля: сначала познакомимся с Python','З нуля: спершу познайомимося з Python','From zero: meet Python first'),
  startLink:T('Никогда не программировал? Начни здесь','Ніколи не програмував? Почни тут','Never programmed? Start here'),
  intro:T('Здесь не нужны знания программирования. Читай по порядку, пробуй маленькие примеры и только потом переходи к заданиям.','Знання програмування тут не потрібні. Читай за порядком, пробуй маленькі приклади й лише потім переходь до завдань.','No programming knowledge is needed. Read in order, try small examples, then move on to the exercises.'),
  detail:T('Разберём тему без спешки','Розберімо тему без поспіху','Let’s take the topic step by step'),
  example:T('Учебный пример','Навчальний приклад','A learning example'),
  lines:T('Что означает каждая строка','Що означає кожен рядок','What each line means'),
  line:T('Строка','Рядок','Line'),
  runs:T('Проверим мысленно на разных значениях','Перевірмо подумки на різних значеннях','Trace it with different values'),
  input:T('Ввод или значение','Ввід або значення','Input or value'),
  output:T('Что увидим','Що побачимо','What we see'),
  why:T('Почему','Чому','Why'),
  rules:T('Правила, которые стоит запомнить','Правила, які варто запам’ятати','Rules to remember'),
  mistakes:T('Частая ошибка — и её причина','Поширена помилка — і її причина','Common mistakes and why they happen'),
  think:T('Перед своей задачей','Перед власним завданням','Before your own exercise'),
  empty:T('Ничего не выводится','Нічого не виводиться','Nothing is printed'),
  online:T('Открыть онлайн-версию','Відкрити онлайн-версію','Open the online version')
};
const basics=[
 {title:T('1. Что такое программа','1. Що таке програма','1. What is a program?'),paragraphs:[
 T('Программа — инструкции для компьютера. Представь рецепт: сначала взять продукты, потом смешать, затем приготовить. Python — язык, на котором мы записываем такие инструкции. Компьютер выполняет записанное, а не угадывает, что мы хотели сказать.','Програма — інструкції для комп’ютера. Уяви рецепт: спершу взяти продукти, потім змішати, далі приготувати. Python — мова, якою ми записуємо такі інструкції. Комп’ютер виконує написане, а не вгадує, що ми хотіли сказати.','A program gives instructions to a computer, like a recipe: get ingredients, mix them, then cook. Python is a language for writing these instructions. The computer follows what we write; it does not guess what we meant.'),
 T('В этом курсе программа обычно получает данные, проверяет их и выводит ответ. Обычные команды выполняются сверху вниз. Условия позволяют некоторые команды выполнить, а другие пропустить.','У цьому курсі програма зазвичай отримує дані, перевіряє їх і виводить відповідь. Звичайні команди виконуються згори вниз. Умови дозволяють виконати одні команди й пропустити інші.','Here a program usually receives data, checks it, and prints an answer. Ordinary instructions run from top to bottom. Conditions let us run some instructions and skip others.')],code:'print(2 + 3)',steps:[T('`print()` выводит результат на экран. Python сначала складывает 2 и 3 внутри скобок, поэтому мы увидим `5`. Слова «print» и знаки скобок нужно писать точно.','`print()` виводить результат на екран. Python спершу додає 2 і 3 у дужках, тому побачимо `5`. Слово «print» і дужки треба писати точно.','`print()` displays a result. Python first adds 2 and 3 inside the parentheses, so we see `5`. Spell print and write the parentheses exactly.')]},
 {title:T('2. Переменная: имя для значения','2. Змінна: назва для значення','2. A variable: a name for a value'),paragraphs:[
 T('Переменная позволяет сохранить значение и обратиться к нему по имени. Представь подписанную коробку: на ней написано `coins`, а внутри лежит число 6. В коде справа от `=` находится значение, слева — имя, под которым его сохраняем.','Змінна дозволяє зберегти значення й звернутися до нього за назвою. Уяви підписану коробку: на ній написано `coins`, а всередині число 6. У коді праворуч від `=` — значення, ліворуч — назва, під якою його зберігаємо.','A variable stores a value under a name. Imagine a box labelled `coins` holding the number 6. In code, the value is on the right of `=` and the name receiving it is on the left.')],code:'coins = 6\nprint(coins)\ncoins = 9\nprint(coins)',steps:[
 T('Первая строка сохраняет 6 под именем `coins`. Вторая выводит 6. Третья заменяет значение на 9, поэтому четвёртая выводит 9. Значение не печатается само: для вывода нужен `print()`.','Перший рядок зберігає 6 під назвою `coins`. Другий виводить 6. Третій змінює значення на 9, тому четвертий виводить 9. Значення не друкується саме: потрібен `print()`.','Line 1 stores 6 as `coins`. Line 2 prints 6. Line 3 changes it to 9, so line 4 prints 9. Assignment alone does not display anything; printing needs `print()`.'),
 T('Используй понятные имена латинскими буквами: `age`, `weather`, `max_val`. В имени не бывает пробелов; вместо пробела можно поставить `_`. `age` и `Age` — разные имена. Сначала создай переменную, потом используй её.','Використовуй зрозумілі назви латинськими літерами: `age`, `weather`, `max_val`. У назві не буває пробілів; замість пробілу можна поставити `_`. `age` та `Age` — різні назви. Спершу створи змінну, потім використовуй її.','Use clear names such as `age`, `weather`, and `max_val`. Names cannot contain spaces; an underscore `_` can separate words. `age` and `Age` are different names. Create a variable before using it.')]},
 {title:T('3. Число и текст — разные значения','3. Число й текст — різні значення','3. Numbers and text are different'),paragraphs:[
 T('`6` без кавычек — число: с ним можно считать. `"6"` в кавычках — текст, даже если он выглядит как число. Текст в Python называют строкой. `"hello"` — тоже строка. Кавычки обозначают текст, но при выводе сами не показываются.','`6` без лапок — число: з ним можна рахувати. `"6"` у лапках — текст, навіть якщо схожий на число. Текст у Python називають рядком. `"hello"` — теж рядок. Лапки позначають текст, але самі під час виводу не показуються.','`6` without quotes is a number you can calculate with. `"6"` in quotes is text, even though it looks like a number. Text in Python is called a string. `"hello"` is also a string. Quotes mark text; they are not printed.')],code:'print(6 + 2)\nprint("6" + "2")\nprint("coins")\ncoins = 6\nprint(coins)',steps:[
 T('Получим четыре строки: `8`, `62`, `coins`, `6`. У чисел `+` выполняет сложение, у двух строк — соединение текста. `print("coins")` печатает слово, а `print(coins)` ищет сохранённое под этим именем значение.','Отримаємо чотири рядки: `8`, `62`, `coins`, `6`. Для чисел `+` виконує додавання, для двох рядків — з’єднання тексту. `print("coins")` друкує слово, а `print(coins)` шукає значення, збережене під цією назвою.','The four outputs are `8`, `62`, `coins`, and `6`. With numbers, `+` adds; with two strings, it joins the text. `print("coins")` prints the word. `print(coins)` looks up the value stored under that name.'),
 T('Для текста подходят обычные прямые кавычки `"..."` или `\'...\'`. Открывающая и закрывающая должны быть одного вида. Без кавычек Python воспримет слово как имя переменной.','Для тексту підходять звичайні прямі лапки `"..."` або `\'...\'`. Початкова й кінцева мають бути одного виду. Без лапок Python сприйме слово як назву змінної.','Use ordinary straight quotes `"..."` or `\'...\'`, with matching opening and closing quotes. Without quotes, Python treats a word as a variable name.')]},
 {title:T('4. input(): получить одну строку','4. input(): отримати один рядок','4. input(): receive one line'),paragraphs:[
 T('`input()` читает данные, которые вводит человек. На нашем сайте данные заранее вписываются в поле «Входные данные». Один вызов `input()` берёт одну строку. Второй вызов берёт следующую, а не ту же самую.','`input()` читає дані, які вводить людина. На нашому сайті їх заздалегідь вписують у поле «Вхідні дані». Один виклик `input()` бере один рядок. Другий бере наступний, а не той самий.','`input()` reads data supplied by a person. On this site, enter it in the Input box before running. One call to `input()` reads one line. The next call reads the next line, not the same one again.')],code:'name = input()\ncity = input()\nprint(name)\nprint(city)',steps:[
 T('Если во входных данных две строки — `Alex` и `Kyiv`, имя получит `Alex`, город — `Kyiv`, а программа выведет их по очереди. В редакторе пишутся команды; в поле ввода — данные без команд и без кавычек.','Якщо у вхідних даних два рядки — `Alex` і `Kyiv`, ім’я отримає `Alex`, місто — `Kyiv`, а програма виведе їх за порядком. У редакторі пишуть команди; у полі вводу — дані без команд і без лапок.','With input lines `Alex` and `Kyiv`, name receives Alex and city receives Kyiv. They print in that order. Write instructions in the code editor and plain data, without commands or quotes, in the Input box.'),
 T('`input()` возвращает текст. Поэтому для слова достаточно `word = input()`. Скобки нужны: `input` без `()` не читает строку. Если вызовов больше, чем строк во вводе, получим ошибку нехватки данных.','`input()` повертає текст. Тому для слова достатньо `word = input()`. Дужки потрібні: `input` без `()` не читає рядок. Якщо викликів більше, ніж рядків вводу, отримаємо помилку нестачі даних.','`input()` returns text, so `word = input()` is enough for a word. Parentheses matter: `input` without `()` does not read anything. Calling input more times than there are input lines causes an end-of-input error.')]},
 {title:T('5. int(input()): получить целое число','5. int(input()): отримати ціле число','5. int(input()): receive an integer'),paragraphs:[
 T('Чтобы считать или сравнивать числа, текст из ввода нужно превратить в число. `int()` превращает подходящий текст в целое число: например, `"7"` в 7, а `"-3"` в −3. Целые числа не имеют дробной части.','Щоб рахувати або порівнювати числа, текст із вводу треба перетворити на число. `int()` перетворює відповідний текст на ціле число: наприклад, `"7"` на 7, а `"-3"` на −3. Цілі числа не мають дробової частини.','To calculate or compare numbers, convert the input text to a number. `int()` turns suitable text into an integer: `"7"` becomes 7 and `"-3"` becomes −3. Integers have no fractional part.')],code:'count = int(input())\nprint(count + 2)',steps:[
 T('Читай вложенные скобки изнутри: сначала `input()` получает текст, потом `int(...)` превращает его в число, затем `=` сохраняет число в `count`. При вводе `7` следующая строка выведет `9`.','Читай вкладені дужки зсередини: спершу `input()` отримує текст, потім `int(...)` перетворює його на число, далі `=` зберігає число в `count`. Для вводу `7` наступний рядок виведе `9`.','Read the nested parentheses from the inside: `input()` receives text, `int(...)` converts it to a number, then `=` stores it in count. Input `7` makes the next line print `9`.'),
 T('У записи две пары скобок: одна у input, другая у int. После такой строки двоеточия нет. Слово или `7.5` не подходит для этого преобразования: программа сообщит ValueError. Для этих задач вводи целые числа, когда этого просит условие.','У записі дві пари дужок: одна в input, інша в int. Після такого рядка двокрапки немає. Слово або `7.5` не підходить для цього перетворення: програма повідомить ValueError. У цих завданнях вводь цілі числа, коли цього вимагає умова.','There are two pairs of parentheses, one for input and one for int. No colon belongs after this assignment. A word or `7.5` cannot be converted this way and gives a ValueError. Use integers when the exercise asks for them.')]},
 {title:T('6. Сравнение: вопрос с ответом «да» или «нет»','6. Порівняння: запитання з відповіддю «так» або «ні»','6. A comparison asks a yes-or-no question'),paragraphs:[
 T('Условие — выражение, которое здесь даёт ответ «верно» или «неверно». В Python эти ответы называются `True` и `False`. При `coins = 6` проверка `coins > 4` верна, а `coins > 8` неверна. Само сравнение не печатает ответ.','Умова — вираз, який тут дає відповідь «істинно» або «хибно». У Python ці відповіді називаються `True` і `False`. Для `coins = 6` перевірка `coins > 4` істинна, а `coins > 8` хибна. Саме порівняння не друкує відповідь.','Here a condition is an expression giving a true-or-false answer. Python calls these answers `True` and `False`. With `coins = 6`, `coins > 4` is true and `coins > 8` is false. A comparison alone does not print an answer.'),
 T('`=` означает «сохрани значение», а `==` — «проверь равенство». Это разные действия. `word == "hello"` сравнивает полученный текст с нужным словом. Большие и маленькие буквы различаются: `"Hello"` не равно `"hello"`.','`=` означає «збережи значення», а `==` — «перевір рівність». Це різні дії. `word == "hello"` порівнює отриманий текст із потрібним словом. Великі й малі літери різняться: `"Hello"` не дорівнює `"hello"`.','`=` means “store this value”, while `==` means “test equality”. They are different operations. `word == "hello"` compares the received text with that word. Case matters: `"Hello"` is not equal to `"hello"`.')],operators:[
 ['>',T('больше: `6 > 4` верно','більше: `6 > 4` істинно','greater than: `6 > 4` is true')],['<',T('меньше: `6 < 4` неверно','менше: `6 < 4` хибно','less than: `6 < 4` is false')],['>=',T('больше или равно: `6 >= 6` верно','більше або дорівнює: `6 >= 6` істинно','greater than or equal: `6 >= 6` is true')],['<=',T('меньше или равно: `6 <= 6` верно','менше або дорівнює: `6 <= 6` істинно','less than or equal: `6 <= 6` is true')],['==',T('равно: `6 == 6` верно','дорівнює: `6 == 6` істинно','equal: `6 == 6` is true')],['!=',T('не равно: `6 != 4` верно','не дорівнює: `6 != 4` істинно','not equal: `6 != 4` is true')]]},
 {title:T('7. Как учиться на этом сайте','7. Як навчатися на цьому сайті','7. How to use this site'),paragraphs:[
 T('Учебные примеры показывают идею и отличаются от задания. Их результат разобран в таблице. Если пробуешь пример в редакторе, используй «Запустить», а свой прежний код сначала сохрани отдельно. «Проверить решение» всегда проверяет требования текущего задания.','Навчальні приклади показують ідею й відрізняються від завдання. Їхній результат розібрано в таблиці. Якщо пробуєш приклад у редакторі, використовуй «Запустити», а свій попередній код спершу збережи окремо. «Перевірити розв’язок» завжди перевіряє вимоги поточного завдання.','Learning examples explain an idea and differ from the exercise. Their results are traced in the table. To try one in the editor, use Run and save your previous code separately first. Check solution always checks the current exercise’s requirements.'),
 T('Открывай онлайн-сайт по ссылке, а не скачанный index.html: для проверки Python нужна страница по HTTP или HTTPS. Дождись «Python готов». Объяснения и интерактивные примеры можно изучать ещё во время загрузки.','Відкривай онлайн-сайт за посиланням, а не завантажений index.html: для перевірки Python потрібна сторінка через HTTP або HTTPS. Дочекайся «Python готовий». Пояснення та інтерактивні приклади можна вивчати ще під час завантаження.','Open the online website, not a downloaded index.html file: Python checking needs a page served over HTTP or HTTPS. Wait for Python to be ready. You can read explanations and explore examples while it loads.'),
 T('В редакторе «Твой код» напиши программу. В поле «Входные данные» впиши только значения: каждое на отдельной строке. «Запустить» проверяет этот ввод. «Проверить решение» запускает несколько заранее подготовленных случаев, включая границы, и сравнивает ответ с заданием.','У редакторі «Твій код» напиши програму. У полі «Вхідні дані» впиши лише значення: кожне в окремому рядку. «Запустити» використовує цей ввід. «Перевірити розв’язок» запускає кілька підготовлених випадків, зокрема межі, й порівнює відповідь із завданням.','Write your program in the code editor. Put only values in the Input box, one per line. Run uses that input. Check solution runs several prepared cases, including boundaries, and compares the answers with the exercise.'),
 T('В учебных заданиях печатай именно требуемый ответ. Дополнительное «Введите число» внутри input или лишний print тоже попадут в вывод и могут не пройти проверку. Слова ответа зависят от выбранного языка.','У навчальних завданнях друкуй саме потрібну відповідь. Додаткове «Введіть число» всередині input або зайвий print також потраплять у вивід і можуть не пройти перевірку. Слова відповіді залежать від обраної мови.','In exercises, print exactly the requested answer. A prompt inside input or an extra print also appears in the output and can make a check fail. Expected words depend on the selected language.'),
 T('Ошибка — подсказка о том, что исправить. SyntaxError: неверная запись, например пропущено `:`. IndentationError: проверь пробелы в начале строк. NameError: имя не создано или написано по-разному. Номер строки показывает, где Python обнаружил проблему; иногда причина в строке перед ней.','Помилка — підказка, що виправити. SyntaxError: неправильний запис, наприклад пропущено `:`. IndentationError: перевір пробіли на початку рядків. NameError: назву не створено або написано по-різному. Номер рядка показує, де Python виявив проблему; іноді причина в попередньому рядку.','An error points to something to fix. SyntaxError means invalid syntax, such as a missing colon. IndentationError asks you to check leading spaces. NameError means a name was not created or was spelled differently. The line number shows where Python noticed the problem; its cause can be on the previous line.')],online:true}
];
const firstIf={
 paragraphs:[T('В жизни мы говорим: «Если холодно, возьму шапку». Решение зависит от температуры. В Python `if` означает «если» и ставит такую проверку перед действием. Действия под условием называют его блоком или веткой.','У житті кажемо: «Якщо холодно, візьму шапку». Рішення залежить від температури. У Python `if` означає «якщо» й ставить таку перевірку перед дією. Дії під умовою називають її блоком або гілкою.','In everyday life: “If it is cold, I’ll take a hat.” The temperature decides the action. Python’s `if` places a check before an action. The instructions under a condition are its block or branch.')],
 example:example(T('temp = int(input())\nif temp < 0:\n    print("Надень шапку")\nprint("Проверка закончена")','temp = int(input())\nif temp < 0:\n    print("Одягни шапку")\nprint("Перевірку завершено")','temp = int(input())\nif temp < 0:\n    print("Take a hat")\nprint("Check finished")'),[
 T('Считываем одну строку, превращаем в целое число и сохраняем в `temp`. Это температура. Имя уже создано, поэтому следующая строка сможет его использовать.','Зчитуємо один рядок, перетворюємо на ціле число й зберігаємо в `temp`. Це температура. Назву вже створено, тому наступний рядок може її використати.','Read one line, convert it to an integer, and store the temperature as temp. The name now exists for the next line to use.'),
 T('Проверяем: температура меньше нуля? Двоеточие в конце означает, что дальше идёт блок действий для ответа «да».','Перевіряємо: температура менша за нуль? Двокрапка наприкінці означає, що далі йде блок дій для відповіді «так».','Check whether the temperature is below zero. The colon at the end introduces the actions for a true result.'),
 T('Четыре пробела связывают print с if. Эта строка выполнится только при верной проверке. Кавычки обозначают текст сообщения.','Чотири пробіли пов’язують print з if. Цей рядок виконається лише за істинної перевірки. Лапки позначають текст повідомлення.','Four leading spaces attach this print to the if. It runs only when the check is true. Quotes mark the message text.'),
 T('Здесь отступа уже нет: мы вышли из блока. Эта команда выполнится после проверки при любой температуре.','Тут відступу вже немає: ми вийшли з блоку. Ця команда виконається після перевірки за будь-якої температури.','No indentation here: we have left the block. This instruction runs after the check for any temperature.')],[
 ['-5',T('Надень шапку\nПроверка закончена','Одягни шапку\nПеревірку завершено','Take a hat\nCheck finished'),T('−5 < 0 верно: выполняются строка 3 и затем строка 4.','−5 < 0 істинно: виконуються рядок 3, потім рядок 4.','−5 < 0 is true, so line 3 runs, then line 4.')],
 ['0',T('Проверка закончена','Перевірку завершено','Check finished'),T('0 < 0 неверно. Строка 3 пропускается, строка 4 остаётся.','0 < 0 хибно. Рядок 3 пропускається, рядок 4 залишається.','0 < 0 is false. Line 3 is skipped; line 4 still runs.')],
 ['7',T('Проверка закончена','Перевірку завершено','Check finished'),T('7 < 0 неверно. Без else у if просто нет действия для ответа «нет».','7 < 0 хибно. Без else в if просто немає дії для відповіді «ні».','7 < 0 is false. Without an else, this if has no action for a false result.')]]),
 rules:[T('Сначала `if`, затем полное условие, затем `:`. На следующей строке — действие с отступом. После if нельзя оставлять пустой блок.','Спершу `if`, потім повна умова, далі `:`. На наступному рядку — дія з відступом. Блок після if не можна залишати порожнім.','Write if, the whole condition, then a colon. On the next line, indent the action. Do not leave the block after if empty.'),T('Используй 4 пробела на каждый уровень. Отступ — часть смысла программы. Команды с одинаковым отступом принадлежат одному блоку.','Використовуй 4 пробіли на кожен рівень. Відступ — частина змісту програми. Команди з однаковим відступом належать до одного блоку.','Use 4 spaces per indentation level. Indentation carries meaning. Instructions at the same indentation belong to the same block.')],
 mistakes:[T('`if temp < 0` без `:` — не законченная запись условия. `print("Текст"):` с двоеточием тоже неверно: обычный print не открывает блок.','`if temp < 0` без `:` — незавершений запис умови. `print("Текст"):` із двокрапкою теж неправильно: звичайний print не відкриває блок.','`if temp < 0` without a colon is incomplete. A colon after an ordinary print is also wrong: print does not introduce a block.')],
 think:T('Прежде чем писать код, скажи словами: «Что я проверяю? Что должно произойти при ответе да? Нужно ли что-нибудь при ответе нет?» Отсутствие вывода иногда и есть правильное поведение.','Перш ніж писати код, скажи словами: «Що я перевіряю? Що має статися за відповіді так? Чи потрібно щось за відповіді ні?» Відсутність виводу іноді й є правильним результатом.','Before coding, say: “What am I checking? What should happen if it is true? Is anything needed if it is false?” Sometimes printing nothing is correct.')
};
const otherwise={
 paragraphs:[T('Если заряд достаточный — используем устройство. Иначе — заряжаем. Здесь нужны два разных действия. `else` добавляет второй путь к своему if и означает «в остальных случаях, когда эта проверка не подошла».','Якщо заряду достатньо — використовуємо пристрій. Інакше — заряджаємо. Тут потрібні дві різні дії. `else` додає другий шлях до свого if й означає «в інших випадках, коли ця перевірка не підійшла».','If there is enough charge, use the device. Otherwise, charge it. We need two different actions. An else adds the second path to its matching if: all cases where that check was false.')],
 example:example(T('charge = int(input())\nif charge >= 30:\n    print("Можно работать")\nelse:\n    print("Заряди устройство")','charge = int(input())\nif charge >= 30:\n    print("Можна працювати")\nelse:\n    print("Заряди пристрій")','charge = int(input())\nif charge >= 30:\n    print("Ready to use")\nelse:\n    print("Charge the device")'),[
 T('Получаем заряд числом. При вводе 30 в charge будет число 30.','Отримуємо заряд числом. Для вводу 30 у charge буде число 30.','Receive the charge as a number. Input 30 stores the number 30 in charge.'),
 T('`>=` — больше или равно. Спрашиваем, есть ли хотя бы 30 процентов. Ровно 30 тоже подходит.','`>=` — більше або дорівнює. Запитуємо, чи є хоча б 30 відсотків. Рівно 30 теж підходить.','>= means greater than or equal. Check for at least 30 percent; exactly 30 qualifies too.'),
 T('Действие для верной проверки, поэтому отступ 4 пробела.','Дія для істинної перевірки, тому відступ 4 пробіли.','The action for a true check uses a 4-space indentation.'),
 T('`else:` стоит на том же уровне, что if. У него нет своего условия: после неверного `charge >= 30` остаются все значения меньше 30.','`else:` стоїть на тому самому рівні, що if. Власної умови немає: після хибного `charge >= 30` залишаються всі значення менші за 30.','else lines up with if. It has no condition of its own: if charge >= 30 is false, every remaining value is below 30.'),
 T('Действие второго пути тоже имеет 4 пробела. Два сообщения из этой пары за один запуск не печатаются.','Дія другого шляху теж має 4 пробіли. Два повідомлення з цієї пари за один запуск не друкуються.','The second-path action also has 4 spaces. This pair never prints both messages in one run.')],[
 ['29',T('Заряди устройство','Заряди пристрій','Charge the device'),T('29 >= 30 неверно → выполняется else.','29 >= 30 хибно → виконується else.','29 >= 30 is false → else runs.')],
 ['30',T('Можно работать','Можна працювати','Ready to use'),T('Равенство включено → выполняется if.','Рівність включено → виконується if.','Equality is included → if runs.')],
 ['31',T('Можно работать','Можна працювати','Ready to use'),T('31 >= 30 верно → else пропускается.','31 >= 30 істинно → else пропускається.','31 >= 30 is true → else is skipped.')]]),
 rules:[T('У else нет проверки и без пары с if он здесь не используется. Верхний if и его else начинаются с 0 пробелов, а их действия — с 4. Во вложенном коде оба слова сдвигаются вместе.','У else немає перевірки, і без пари з if він тут не використовується. Зовнішній if та його else починаються з 0 пробілів, їхні дії — з 4. У вкладеному коді обидва слова зсуваються разом.','Else has no check and needs a matching if here. At top level, if and else have 0 leading spaces and their actions have 4. Inside another block, move both keywords together.'),
 T('Для следующей задачи полезно `%`: это остаток от деления. `11 % 4` равно 3: 11 = 4 × 2 + 3. `12 % 4` равно 0: число разделилось без остатка. Здесь `%` не означает «проценты».','Для наступного завдання корисно `%`: це остача від ділення. `11 % 4` дорівнює 3: 11 = 4 × 2 + 3. `12 % 4` дорівнює 0: число поділилося без остачі. Тут `%` не означає «відсотки».','The next exercise uses % for a remainder. `11 % 4` is 3 because 11 = 4 × 2 + 3. `12 % 4` is 0 because it divides exactly. Here % does not mean a percentage.')],
 mistakes:[T('`else charge < 30:` — неверно, потому что else не принимает условие. Просто `else:` уже покрывает нужный оставшийся случай. Если сдвинуть else под print, он перестанет совпадать по уровню со своим if.','`else charge < 30:` — неправильно, бо else не приймає умову. Просто `else:` вже охоплює потрібний випадок, що залишився. Якщо зсунути else під print, він не збігатиметься за рівнем зі своїм if.','`else charge < 30:` is invalid because else does not take a condition. `else:` already covers the remaining case. Indenting else under print breaks its alignment with if.')],
 think:T('Проверь три значения: на единицу меньше границы, ровно границу, на единицу больше. Так легко заметить разницу между > и >=.','Перевір три значення: на одиницю менше межі, рівно межу, на одиницю більше. Так легко помітити різницю між > та >=.','Try one below the boundary, the boundary itself, and one above. This reveals the difference between > and >=.')
};
const alternatives={
 paragraphs:[T('Иногда двух путей мало. Для дождя нужен зонт, для снега — тёплая обувь, для солнца — прогулка. `elif` читается «иначе, если»: новая проверка проводится лишь после неудачи предыдущих. Это одна цепочка выбора.','Іноді двох шляхів мало. Для дощу потрібна парасоля, для снігу — тепле взуття, для сонця — прогулянка. `elif` читається «інакше, якщо»: нову перевірку виконують лише після невдачі попередніх. Це один ланцюжок вибору.','Sometimes two paths are not enough: rain calls for an umbrella, snow for boots, sun for a walk. Elif means “otherwise, if”. Its check is reached only after earlier checks are false. These form one decision chain.')],
 example:example(T('weather = input()\nif weather == "rain":\n    print("Возьми зонт")\nelif weather == "snow":\n    print("Надень сапоги")\nelse:\n    print("Посмотри в окно")','weather = input()\nif weather == "rain":\n    print("Візьми парасолю")\nelif weather == "snow":\n    print("Одягни чоботи")\nelse:\n    print("Подивись у вікно")','weather = input()\nif weather == "rain":\n    print("Take an umbrella")\nelif weather == "snow":\n    print("Wear boots")\nelse:\n    print("Look outside")'),[
 T('Читаем текст. В этом примере ввод — английское слово без кавычек: rain или snow. int не нужен.','Читаємо текст. У цьому прикладі ввід — англійське слово без лапок: rain або snow. int не потрібен.','Read text. For this example, input the English word rain or snow without quotes. No int is needed.'),
 T('Сравниваем текст с "rain". Двойное равенство проверяет, одинаковы ли значения.','Порівнюємо текст із "rain". Подвійна рівність перевіряє, чи однакові значення.','Compare the text with "rain". Double equals checks whether the values match.'),
 T('При совпадении печатаем сообщение и пропускаем остальные пути цепочки.','За збігу друкуємо повідомлення й пропускаємо решту шляхів ланцюжка.','On a match, print this message and skip the remaining branches.'),
 T('До elif доходим, только если это не rain. Теперь проверяем snow. Двоеточие ставится после всего сравнения.','До elif доходимо, лише якщо це не rain. Тепер перевіряємо snow. Двокрапка йде після всього порівняння.','Reach elif only when the input is not rain. Now check for snow. The colon follows the entire comparison.'),
 T('Сообщение для snow имеет отступ и принадлежит именно elif.','Повідомлення для snow має відступ і належить саме elif.','The snow message is indented under, and belongs to, this elif.'),
 T('Все предыдущие проверки не подошли. Сюда попадёт sun, неизвестное слово или любой другой текст, даже с ошибкой.','Усі попередні перевірки не підійшли. Сюди потрапить sun, невідоме слово або будь-який інший текст, навіть із помилкою.','Every previous check was false. This includes sun, an unknown word, or any other text, even a typo.'),
 T('Печатаем запасное сообщение. Else не знает смысл погоды: он лишь ловит оставшиеся значения.','Друкуємо запасне повідомлення. Else не знає значення погоди: він лише охоплює решту значень.','Print the fallback message. Else does not understand weather; it simply handles the remaining values.')],[
 ['rain',T('Возьми зонт','Візьми парасолю','Take an umbrella'),T('Первое сравнение верно. Elif и else пропускаются.','Перше порівняння істинне. Elif та else пропускаються.','The first check is true; elif and else are skipped.')],
 ['snow',T('Надень сапоги','Одягни чоботи','Wear boots'),T('Первый if неверен, следующий elif верен.','Перший if хибний, наступний elif істинний.','The if is false, but the elif is true.')],
 ['abracadabra',T('Посмотри в окно','Подивись у вікно','Look outside'),T('Ни одно сравнение не подошло. Выполняется else.','Жодне порівняння не підійшло. Виконується else.','Neither comparison matches, so else runs.')]]),
 rules:[T('If начинает цепочку. Elif может быть несколько. Else, если нужен, завершает её. Все эти слова стоят на одном уровне. В такой цепочке выполняется первая подходящая ветка; без else может не выполниться ни одна.','If починає ланцюжок. Elif може бути кілька. Else, якщо потрібен, завершує його. Усі ці слова стоять на одному рівні. Виконується перша відповідна гілка; без else може не виконатися жодна.','If starts the chain. Several elif branches may follow. Else, if needed, ends it. All keywords align. The first matching branch runs; without else, none may run.'),
 T('Отдельные if — отдельные проверки. Несколько из них могут сработать за один запуск. Если нужен один выбор из нескольких, используй цепочку if/elif/else.','Окремі if — окремі перевірки. Кілька можуть спрацювати за один запуск. Якщо потрібен один вибір із кількох, використовуй ланцюжок if/elif/else.','Separate if statements are independent checks, and several can run. Use an if/elif/else chain when you want one choice from several.'),
 T('`and` — обе проверки верны; `or` — хотя бы одна. Например, `temp >= 5 and temp <= 20` проверяет обе границы, а `weather == "rain" or weather == "snow"` — любой из двух вариантов. По обе стороны пиши полную проверку.','`and` — обидві перевірки істинні; `or` — хоча б одна. Наприклад, `temp >= 5 and temp <= 20` перевіряє обидві межі, а `weather == "rain" or weather == "snow"` — будь-який із двох варіантів. З обох боків пиши повну перевірку.','And needs both checks to be true; or needs at least one. `temp >= 5 and temp <= 20` checks both bounds. `weather == "rain" or weather == "snow"` allows either word. Write a complete comparison on each side.')],
 mistakes:[T('`elif:` без условия неверно. `elif weather == "snow"` без двоеточия тоже неверно. В цепочке проверки идут по порядку: 95 подходит и под >= 50, и под >= 90, поэтому широкий порог первым может забрать случай высокого результата.','`elif:` без умови неправильно. `elif weather == "snow"` без двокрапки теж неправильно. Перевірки йдуть за порядком: 95 підходить і під >= 50, і під >= 90, тому широкий поріг першим може забрати випадок високого результату.','Elif without a condition is invalid, and its condition needs a trailing colon. Order matters: 95 matches both >= 50 and >= 90. A broad threshold placed first can intercept the high result.')],
 think:T('Проверь по одному вводу для каждой ветки и один неизвестный ввод. Не угадывай по смыслу слова: пройди проверки сверху вниз.','Перевір по одному вводу для кожної гілки й один невідомий ввід. Не вгадуй за змістом слова: пройди перевірки згори вниз.','Try one input for every branch and an unknown input. Do not guess from the word’s meaning; follow the checks from top to bottom.')
};
const nested={
 paragraphs:[T('Второй вопрос иногда имеет смысл только после первого. Сначала решаем, можно ли отправить посылку обычным способом; только потом спрашиваем, хрупкая ли она. Внутренний if — часть внешней ветки. Если в эту ветку не вошли, не выполняются ни её input, ни её проверки.','Друге запитання іноді має сенс лише після першого. Спершу вирішуємо, чи можна відправити посилку звичайним способом; лише потім запитуємо, чи вона крихка. Внутрішній if — частина зовнішньої гілки. Якщо до неї не потрапили, не виконуються ні її input, ні її перевірки.','A second question sometimes matters only after the first. First decide whether a parcel fits ordinary delivery; only then ask whether it is fragile. The inner if belongs to the outer branch. If that branch is skipped, its inputs and checks are skipped too.')],
 example:example(T('weight = int(input())\nif weight <= 5:\n    fragile = input()\n    if fragile == "yes":\n        print("Упакуй осторожно")\n    else:\n        print("Обычная упаковка")\nelse:\n    print("Нужна большая коробка")','weight = int(input())\nif weight <= 5:\n    fragile = input()\n    if fragile == "yes":\n        print("Пакуй обережно")\n    else:\n        print("Звичайне пакування")\nelse:\n    print("Потрібна велика коробка")','weight = int(input())\nif weight <= 5:\n    fragile = input()\n    if fragile == "yes":\n        print("Pack carefully")\n    else:\n        print("Regular packaging")\nelse:\n    print("Use a large box")'),[
 T('Читаем вес с первой строки ввода.','Зчитуємо вагу з першого рядка вводу.','Read the weight from the first input line.'),
 T('Внешняя проверка: вес не больше 5? Эта строка без отступа.','Зовнішня перевірка: вага не більша за 5? Цей рядок без відступу.','The outer check asks whether the weight is at most 5. It has no indentation.'),
 T('4 пробела: читаем вторую строку только при подходящем весе. Во вводе для веса 6 вторую строку не требуют.','4 пробіли: читаємо другий рядок лише за відповідної ваги. Для ваги 6 другий рядок вводу не потрібен.','4 spaces: read a second line only for a qualifying weight. Input for weight 6 does not need that line.'),
 T('4 пробела: внутренняя проверка хрупкости находится внутри внешнего if.','4 пробіли: внутрішня перевірка крихкості міститься всередині зовнішнього if.','4 spaces: the fragility check is inside the outer if.'),
 T('8 пробелов: действие внутри двух блоков. Нужно, чтобы обе проверки привели сюда.','8 пробілів: дія всередині двох блоків. Потрібно, щоб обидві перевірки привели сюди.','8 spaces: an action inside two blocks. Both decisions must lead here.'),
 T('4 пробела: этот else — пара внутреннему if из строки 4.','4 пробіли: цей else — пара внутрішньому if з рядка 4.','4 spaces: this else belongs to the inner if on line 4.'),
 T('8 пробелов: действие внутреннего else.','8 пробілів: дія внутрішнього else.','8 spaces: the inner else action.'),
 T('0 пробелов: этот else — пара внешнему if из строки 2.','0 пробілів: цей else — пара зовнішньому if з рядка 2.','0 spaces: this else belongs to the outer if on line 2.'),
 T('4 пробела: действие внешнего else. В этой ветке fragile вообще не читается.','4 пробіли: дія зовнішнього else. У цій гілці fragile взагалі не зчитується.','4 spaces: the outer else action. This branch never reads fragile.')],[
 ['3\nyes',T('Упакуй осторожно','Пакуй обережно','Pack carefully'),T('3 <= 5 верно → читаем yes → внутренний if верен.','3 <= 5 істинно → читаємо yes → внутрішній if істинний.','3 <= 5 is true → read yes → the inner if is true.')],
 ['3\nno',T('Обычная упаковка','Звичайне пакування','Regular packaging'),T('Внешний if верен, внутренний неверен → его else.','Зовнішній if істинний, внутрішній хибний → його else.','The outer if is true, the inner if is false → its else.')],
 ['6',T('Нужна большая коробка','Потрібна велика коробка','Use a large box'),T('Внешний if неверен → сразу внешний else. Второй input пропущен.','Зовнішній if хибний → одразу зовнішній else. Другий input пропущено.','The outer if is false → its else immediately. The second input is skipped.')]]),
 rules:[T('Каждый else ставится на одной вертикальной линии со своим if. Сначала найди пары, затем проверь отступы: внешний уровень 0, внутри 4, внутри внутреннего блока 8.','Кожен else ставиться на одній вертикальній лінії зі своїм if. Спершу знайди пари, потім перевір відступи: зовнішній рівень 0, усередині 4, усередині внутрішнього блоку 8.','Every else aligns with its own if. Find the pairs, then check indentation: 0 outside, 4 inside, 8 inside the inner block.'),T('Дополнительный input расположи в той ветке, которой эти данные нужны. Переменная, созданная только внутри ветки, может не существовать при другом пути.','Додатковий input розташуй у тій гілці, якій потрібні ці дані. Змінна, створена лише всередині гілки, може не існувати за іншого шляху.','Place optional input inside the branch that needs it. A variable created only in a branch might not exist on a different path.')],
 mistakes:[T('Если внутренний if убрать к левому краю, он станет отдельной проверкой, а не вложенной. Если прочитать fragile до внешнего if, программа попросит второй ввод даже для веса 6.','Якщо прибрати відступ внутрішнього if, він стане окремою перевіркою. Якщо прочитати fragile до зовнішнього if, програма вимагатиме другий ввід навіть для ваги 6.','Moving the inner if to the left makes it independent. Reading fragile before the outer if would require a second input even for weight 6.')],
 think:T('Нарисуй три пути: внешний ответ «нет»; внешний «да» и внутренний «да»; внешний «да» и внутренний «нет». Для каждого укажи, сколько строк ввода нужно.','Намалюй три шляхи: зовнішня відповідь «ні»; зовнішня «так» і внутрішня «так»; зовнішня «так» і внутрішня «ні». Для кожного зазнач, скільки рядків вводу потрібно.','Draw three paths: outer false; outer true and inner true; outer true and inner false. Count the input lines required for each path.')
};
const updateValue={
 paragraphs:[
 T('Переменная хранит текущее значение. Например, `money = 80` сохраняет число 80 под именем money. Если потратить 20, нужно вычислить остаток и сохранить его вместо прежнего числа. Само значение не изменится от слов в условии задания.','Змінна зберігає поточне значення. Наприклад, `money = 80` зберігає число 80 під назвою money. Якщо витратити 20, треба обчислити залишок і зберегти його замість попереднього числа. Саме значення не зміниться від слів в умові завдання.','A variable holds its current value. For example, `money = 80` stores 80 under the name money. After spending 20, calculate what remains and store it in place of the previous number. The exercise instructions alone do not change the value.'),
 T('Для этого пишут `money = money - 20`. Читай: «Возьми текущее money, вычти 20 и сохрани результат обратно в money». Имя справа берёт старое значение. Имя слева указывает, куда сохранить новое.','Для цього пишуть `money = money - 20`. Читай: «Візьми поточне money, відніми 20 і збережи результат назад у money». Назва праворуч бере старе значення. Назва ліворуч указує, куди зберегти нове.','Write `money = money - 20`. Read it as “take the current money, subtract 20, and store the result back in money”. The name on the right reads the old value. The name on the left says where to store the new value.'),
 T('В Python `=` — команда сохранить результат, а не знак математического равенства. Поэтому одинаковое имя с двух сторон допустимо. Сначала Python вычисляет всё справа от `=`, и только потом заменяет значение слева. Для проверки равенства используют `==`.','У Python `=` — команда зберегти результат, а не знак математичної рівності. Тому однакова назва з обох боків допустима. Спершу Python обчислює все праворуч від `=`, а лише потім замінює значення ліворуч. Для перевірки рівності використовують `==`.','In Python, `=` instructs the computer to store a result; it is not mathematical equality. Using the same name on both sides is allowed. Python evaluates everything on the right first, then replaces the value on the left. Use `==` to test equality.')],
 example:example(T('money = int(input())\nmoney = money - 20\nprint(money)','money = int(input())\nmoney = money - 20\nprint(money)','money = int(input())\nmoney = money - 20\nprint(money)'),[
 T('Читаем целое число и сохраняем его в money. Например, ввели 80 — теперь money хранит 80. Число должно быть сохранено до следующей строки.','Читаємо ціле число й зберігаємо його в money. Наприклад, ввели 80 — тепер money зберігає 80. Число має бути збережене до наступного рядка.','Read an integer and store it in money. Entering 80 makes money hold 80. The number must be stored before the next line.'),
 T('Берём старое money: 80. Вычисляем справа `80 - 20`: получается 60. Затем `=` сохраняет 60 в money вместо 80. Эта строка ничего не выводит. При другом вводе вычитаем из другого числа: программа не привязана к 80.','Беремо старе money: 80. Обчислюємо праворуч `80 - 20`: отримуємо 60. Потім `=` зберігає 60 у money замість 80. Цей рядок нічого не виводить. Для іншого вводу віднімаємо від іншого числа: програма не прив’язана до 80.','Read the old money: 80. Evaluate `80 - 20` on the right to get 60. Then `=` stores 60 in money, replacing 80. This line prints nothing. With a different input, subtract from that number; the program is not tied to 80.'),
 T('Выводим последнее сохранённое значение. При вводе 80 увидим 60. У имени money здесь нет кавычек: нужны его данные, а не слово «money».','Виводимо останнє збережене значення. Для вводу 80 побачимо 60. Назва money тут без лапок: потрібні її дані, а не слово «money».','Print the most recently stored value. Input 80 prints 60. The name money has no quotes here: we need its value, not the word “money”.')],[
 ['80',T('60','60','60'),T('Сначала money хранит 80, после вычитания — 60. Печатаем уже изменённое число.','Спершу money зберігає 80, після віднімання — 60. Друкуємо вже змінене число.','Money starts at 80 and becomes 60 after the subtraction. Print the updated number.')],
 ['45',T('25','25','25'),T('Та же запись берёт 45 из переменной: 45 − 20 = 25.','Той самий запис бере 45 зі змінної: 45 − 20 = 25.','The same statement reads 45 from the variable: 45 − 20 = 25.')],
 ['20',T('0','0','0'),T('После вычитания остаётся ноль. Ноль — тоже значение, которое можно сохранить и вывести.','Після віднімання залишається нуль. Нуль — теж значення, яке можна зберегти й вивести.','Subtracting leaves zero. Zero is a value that can be stored and printed too.')],
 ['0',T('-20','-20','-20'),T('В этом примере ограничений нет: 0 − 20 даёт −20. Если нужна защита от отрицательного остатка, её отдельно описывают в задании.','У цьому прикладі обмежень немає: 0 − 20 дає −20. Якщо потрібен захист від від’ємного залишку, його окремо описують у завданні.','This example has no restrictions: 0 − 20 gives −20. An exercise must specify any rule preventing a negative balance.')]]),
 trace:{title:T('Одна строка — три шага','Один рядок — три кроки','One statement, three steps'),columns:[T('Шаг','Крок','Step'),T('Что делает Python','Що робить Python','What Python does'),T('Значение','Значення','Value')],rows:[
 [T('1. Прочитать','1. Прочитати','1. Read'),T('Имя money справа берёт текущее сохранённое число.','Назва money праворуч бере поточне збережене число.','The name money on the right reads the current stored number.'),T('80','80','80')],
 [T('2. Посчитать','2. Обчислити','2. Calculate'),T('Вычислить правую часть: `80 - 20`. Пока money ещё хранит 80.','Обчислити праву частину: `80 - 20`. Поки що money зберігає 80.','Evaluate the right-hand side: `80 - 20`. Money still holds 80 at this point.'),T('60','60','60')],
 [T('3. Сохранить','3. Зберегти','3. Store'),T('Знак `=` заменяет значение money готовым результатом.','Знак `=` замінює значення money готовим результатом.','The `=` sign replaces money with the calculated result.'),T('money → 60','money → 60','money → 60')]]},
 rules:[
 T('Чтобы увеличить число на 5, можно написать `money = money + 5`. Чтобы уменьшить на 20 — `money = money - 20`. Здесь число без кавычек, потому что выполняется расчёт.','Щоб збільшити число на 5, можна написати `money = money + 5`. Щоб зменшити на 20 — `money = money - 20`. Число без лапок, бо виконується обчислення.','To increase a number by 5, write `money = money + 5`. To decrease it by 20, write `money = money - 20`. Use numbers without quotes because this is a calculation.'),
 T('Если изменение зависит от условия, помести строку изменения внутри нужного if с отступом. При неверном условии эта строка пропускается, и сохранённое число остаётся прежним.','Якщо зміна залежить від умови, розмісти рядок зміни всередині потрібного if з відступом. За хибної умови цей рядок пропускається, і збережене число залишається попереднім.','If an update depends on a condition, indent the update inside the relevant if. When the condition is false, that statement is skipped and the stored number stays the same.'),
 T('Порядок действий: сохранить начальное число → выполнить нужные изменения → вывести итог. Если итог нужен при любом ответе, print пишется после всего if без отступа.','Порядок дій: зберегти початкове число → виконати потрібні зміни → вивести підсумок. Якщо підсумок потрібен за будь-якої відповіді, print пишеться після всього if без відступу.','Work in order: store the starting number → apply the required updates → print the result. If every answer needs a result, put print after the entire if, without indentation.')],
 mistakes:[
 T('`money = 20` заменяет значение числом 20; вычитания здесь нет. `money = money = 20` тоже сохраняет 20. Чтобы посчитать остаток, справа нужна операция вычитания со старым money.','`money = 20` замінює значення числом 20; віднімання тут немає. `money = money = 20` теж зберігає 20. Щоб обчислити залишок, праворуч потрібна операція віднімання зі старим money.','`money = 20` replaces the value with 20; it does not subtract. `money = money = 20` stores 20 too. To calculate what remains, the right-hand side must subtract from the old money.'),
 T('`money - 20` само по себе не сохраняет результат. `print(money - 20)` выводит результат, но тоже не меняет money. Чтобы следующая строка использовала новое число, сохрани результат через `=`.','`money - 20` саме по собі не зберігає результат. `print(money - 20)` виводить результат, але теж не змінює money. Щоб наступний рядок використав нове число, збережи результат через `=`.','`money - 20` by itself does not store the result. `print(money - 20)` displays the result but also leaves money unchanged. Store the result with `=` so the next statement can use the new number.')],
 think:T('Было money = 90. После money = money - 20 какое число хранится? А если следующая строка money = money + 5? Проследи два изменения по порядку, затем попробуй написать и запустить эти строки.','Було money = 90. Після money = money - 20 яке число зберігається? А якщо наступний рядок money = money + 5? Простеж дві зміни за порядком, потім спробуй написати й запустити ці рядки.','Start with money = 90. What is stored after money = money - 20? What if the next statement is money = money + 5? Trace both updates in order, then try writing and running them.')
};

const shortChoice={
 paragraphs:[
 T('Короткая запись if/else выбирает одно из двух значений и позволяет сохранить его в переменную. Например, выбираем текст о температуре. Сначала разберём обычный вариант, затем запишем тот же выбор одной строкой.','Короткий запис if/else обирає одне з двох значень і дозволяє зберегти його у змінну. Наприклад, обираємо текст про температуру. Спершу розберімо звичайний варіант, потім запишімо той самий вибір одним рядком.','A conditional expression chooses one of two values and lets us store it in a variable. For example, choose a message about the temperature. First read the ordinary version, then write the same choice in one line.'),
 T('Переменная label будет хранить выбранный текст. Label — обычное имя, которое мы придумали, а не команда Python. Текст в кавычках — возможное значение этой переменной.','Змінна label зберігатиме обраний текст. Label — звичайна назва, яку ми придумали, а не команда Python. Текст у лапках — можливе значення цієї змінної.','The variable label will hold the chosen text. Label is an ordinary name we chose, not a Python command. Text in quotes is a possible value of that variable.'),
 T('В обычной записи: если температура ниже 10, сохраняем «Прохладно», иначе — «Тепло». Оба пути создают одну и ту же переменную label. Только после выбора выводим её значение.','У звичайному записі: якщо температура нижча за 10, зберігаємо «Прохолодно», інакше — «Тепло». Обидва шляхи створюють ту саму змінну label. Лише після вибору виводимо її значення.','In the ordinary version, a temperature below 10 stores “Cool”; otherwise, it stores “Warm”. Both paths create the same variable label. Print its value only after making the choice.')],
 before:T('if temp < 10:\n    label = "Прохладно"\nelse:\n    label = "Тепло"','if temp < 10:\n    label = "Прохолодно"\nelse:\n    label = "Тепло"','if temp < 10:\n    label = "Cool"\nelse:\n    label = "Warm"'),
 example:example(T('temp = int(input())\nlabel = "Прохладно" if temp < 10 else "Тепло"\nprint(label)','temp = int(input())\nlabel = "Прохолодно" if temp < 10 else "Тепло"\nprint(label)','temp = int(input())\nlabel = "Cool" if temp < 10 else "Warm"\nprint(label)'),[
 T('Получаем температуру числом. Например, при вводе 9 переменная temp хранит 9.','Отримуємо температуру числом. Наприклад, для вводу 9 змінна temp зберігає 9.','Read the temperature as a number. Input 9 makes temp hold 9.'),
 T('Сначала задаём вопрос из середины строки: temp < 10? При 9 ответ «да» — выбираем текст перед if. При 20 ответ «нет» — выбираем текст после else. Выбирается только одно значение. Затем единственный знак = сохраняет его в label.','Спершу ставимо запитання із середини рядка: temp < 10? Для 9 відповідь «так» — обираємо текст перед if. Для 20 відповідь «ні» — обираємо текст після else. Обирається лише одне значення. Потім єдиний знак = зберігає його у label.','Start with the question in the middle: temp < 10? At 9 the answer is true, so choose the text before if. At 20 it is false, so choose the text after else. Only one value is chosen. The single = then stores it in label.'),
 T('Выводим сохранённый текст: для 9 увидим «Прохладно». print(label) берёт значение переменной. print("label") напечатал бы само слово label.','Виводимо збережений текст: для 9 побачимо «Прохолодно». print(label) бере значення змінної. print("label") надрукував би саме слово label.','Print the stored text: input 9 displays “Cool”. `print(label)` reads the variable’s value. `print("label")` would display the word label itself.')],[
 ['9',T('Прохладно','Прохолодно','Cool'),T('9 < 10 верно → берём значение перед if → сохраняем в label → печатаем.','9 < 10 істинно → беремо значення перед if → зберігаємо у label → друкуємо.','9 < 10 is true → choose the value before if → store it in label → print.')],
 ['10',T('Тепло','Тепло','Warm'),T('10 < 10 неверно: равные числа не подходят под «меньше». Берём текст после else.','10 < 10 хибно: рівні числа не підходять під «менше». Беремо текст після else.','10 < 10 is false: equal numbers do not satisfy “less than”. Choose the text after else.')],
 ['20',T('Тепло','Тепло','Warm'),T('20 < 10 неверно → выбираем второй текст. Условие берёт текущее temp, а не всегда число 9 из примера.','20 < 10 хибно → обираємо другий текст. Умова бере поточне temp, а не завжди число 9 із прикладу.','20 < 10 is false → choose the second text. The condition reads the current temp, not always the example value 9.')]]),
 rules:[
 T('Форма: `имя = значение_да if условие else значение_нет`. Слева имя переменной. Сразу после = — значение для верного условия. После else — значение для неверного.','Форма: `назва = значення_так if умова else значення_ні`. Ліворуч назва змінної. Одразу після = — значення для істинної умови. Після else — значення для хибної.','Pattern: `name = true_value if condition else false_value`. The variable name is on the left. Immediately after = is the value for a true condition. After else is the value for a false condition.'),
 T('Заполняй три места по отдельности: какой вопрос проверяем? Что сохраняем при ответе «да»? Что сохраняем при ответе «нет»? Условие может сравнивать числа, а выбранные значения могут быть текстом.','Заповнюй три місця окремо: яке запитання перевіряємо? Що зберігаємо за відповіді «так»? Що зберігаємо за відповіді «ні»? Умова може порівнювати числа, а обрані значення можуть бути текстом.','Fill three parts separately: what question do we check? What do we store when true? What do we store when false? A condition can compare numbers while the chosen values are text.'),
 T('Двоеточий в короткой записи нет. Один знак = стоит перед всем выбором; повторять имя = после else не нужно. Чтобы выбрать текст, заключи оба варианта текста в кавычки.','Двокрапок у короткому записі немає. Один знак = стоїть перед усім вибором; повторювати назва = після else не потрібно. Щоб обрати текст, візьми обидва варіанти тексту в лапки.','A conditional expression has no colons. One = precedes the whole choice; do not repeat name = after else. To choose text, put both text values in quotes.'),
 T('Сначала сохраняем выбранное значение, затем меняем его, если задача требует, и в конце печатаем. Короткая запись выбирает значение; для нескольких действий подходит обычный if с отступами.','Спершу зберігаємо обране значення, потім змінюємо його, якщо завдання вимагає, і наприкінці друкуємо. Короткий запис обирає значення; для кількох дій підходить звичайний if з відступами.','Store the chosen value first, update it if required, and print at the end. A conditional expression chooses a value; an ordinary indented if works for several actions.')],
 mistakes:[
 T('`label = ... else: ...` — лишнее двоеточие. `print(label)` до присваивания обращается к ещё не созданной переменной. `max val` содержит пробел; допустимое имя — max_val.','`label = ... else: ...` — зайва двокрапка. `print(label)` до присвоєння звертається до ще не створеної змінної. `max val` містить пробіл; допустима назва — max_val.','A colon after else is wrong in a conditional expression. Printing label before assignment reads a variable that does not exist yet. Max val contains a space; max_val is a valid name.'),
 T('Числа в примерах показывают, что можно ввести. В проверке используй имя переменной: при другом вводе её значение изменится. Запись с постоянными числами вроде 9 < 10 даст один и тот же выбор при любом вводе.','Числа у прикладах показують, що можна ввести. У перевірці використовуй назву змінної: для іншого вводу її значення зміниться. Запис зі сталими числами на кшталт 9 < 10 дасть той самий вибір для будь-якого вводу.','Example numbers show possible inputs. Use the variable name in the condition so a different input can change the choice. A fixed check such as 9 < 10 makes the same choice for every input.')],
 think:T('До написания строки назови отдельно условие и два возможных значения. Проверь мысленно один ввод для «да» и один для «нет». Если нужно изменить выбранное число, открой тему «Изменение переменной», затем вернись к практике.','До написання рядка назви окремо умову та два можливі значення. Перевір подумки один ввід для «так» й один для «ні». Якщо треба змінити обране число, відкрий тему «Зміна змінної», потім повернися до практики.','Before writing the statement, identify the condition and the two possible values separately. Trace one true input and one false input. If the chosen number needs updating, read “Updating a variable”, then return to practice.')
};

const logic={
 paragraphs:[T('`and` и `or` объединяют проверки, а не действия. Чтобы вода была подходящей температуры, она должна быть и не слишком холодной, и не слишком горячей: нужны обе границы. Чтобы взять дождевик, достаточно дождя или снега: подходит любой один вариант.','`and` та `or` поєднують перевірки, а не дії. Щоб вода мала відповідну температуру, вона має бути і не надто холодною, і не надто гарячою: потрібні обидві межі. Щоб взяти дощовик, достатньо дощу або снігу: підходить будь-який один варіант.','And and or combine checks, not actions. Suitable water must be neither too cold nor too hot: both bounds must pass. A raincoat can be needed for rain or snow: either matching alternative is enough.')],
 example:example(T('temp = int(input())\nif temp >= 10 and temp <= 25:\n    print("Комфортная температура")\nelse:\n    print("За пределами диапазона")','temp = int(input())\nif temp >= 10 and temp <= 25:\n    print("Комфортна температура")\nelse:\n    print("Поза діапазоном")','temp = int(input())\nif temp >= 10 and temp <= 25:\n    print("Comfortable temperature")\nelse:\n    print("Outside the range")'),[
 T('Читаем число, которое нужно сравнить с двумя границами.','Читаємо число, яке треба порівняти з двома межами.','Read the number to compare with both bounds.'),T('Первая проверка: не меньше 10. Вторая: не больше 25. And требует, чтобы обе дали да.','Перша перевірка: не менше 10. Друга: не більше 25. And вимагає, щоб обидві дали так.','The first check requires at least 10. The second requires at most 25. And needs both to be true.'),T('Сюда попадаем только внутри диапазона, включая его края.','Сюди потрапляємо лише всередині діапазону, включно з краями.','This runs only inside the range, including its endpoints.'),T('Если хотя бы одна граница нарушена, вся проверка с and неверна.','Якщо порушено хоча б одну межу, вся перевірка з and хибна.','If either bound fails, the entire and check is false.'),T('Выводим сообщение для всех значений вне диапазона.','Виводимо повідомлення для всіх значень поза діапазоном.','Print the message for all out-of-range values.')],[
 ['9',T('За пределами диапазона','Поза діапазоном','Outside the range'),T('Первая проверка неверна; одной верной второй недостаточно.','Перша перевірка хибна; однієї істинної другої недостатньо.','The first check is false. The true second check alone is not enough.')],
 ['10',T('Комфортная температура','Комфортна температура','Comfortable temperature'),T('Обе проверки верны; нижняя граница включена.','Обидві перевірки істинні; нижню межу включено.','Both are true; the lower endpoint is included.')],
 ['26',T('За пределами диапазона','Поза діапазоном','Outside the range'),T('Вторая проверка неверна; первая одна не спасает.','Друга перевірка хибна; лише першої недостатньо.','The second check is false; the first alone is not enough.')]]),
 rules:[T('Для or запиши, например, `weather == "rain" or weather == "snow"`. Если совпало одно слово, вся проверка верна. Если не совпало ни одно — неверна.','Для or запиши, наприклад, `weather == "rain" or weather == "snow"`. Якщо збіглося одне слово, вся перевірка істинна. Якщо жодне — хибна.','For or, write `weather == "rain" or weather == "snow"`. Either match makes the whole check true. No match makes it false.'),T('Два отдельных if могут вывести два сообщения. Цепочка if/elif выбирает одну ветку. Сначала реши, какой из этих вариантов требует задача.','Два окремі if можуть вивести два повідомлення. Ланцюжок if/elif обирає одну гілку. Спершу виріши, який варіант потрібен у завданні.','Two independent if statements can print two messages. An if/elif chain chooses one branch. Decide which behavior the exercise needs.')],
 mistakes:[T('`weather == "rain" or "snow"` не сравнивает weather со snow. Непустой текст сам считается истинным, поэтому такой or оказывается верным независимо от weather. Повтори имя и == в обеих проверках.','`weather == "rain" or "snow"` не порівнює weather зі snow. Непорожній текст сам вважається істинним, тому такий or істинний незалежно від weather. Повтори назву та == в обох перевірках.','`weather == "rain" or "snow"` never compares weather with snow. A non-empty string is truthy, so this or is true regardless of weather. Repeat the name and == in both comparisons.')],
 think:T('Для and попробуй: обе проверки верны; только одна верна; обе неверны. Для or попробуй каждый разрешённый вариант и одно неизвестное слово.','Для and спробуй: обидві перевірки істинні; лише одна істинна; обидві хибні. Для or спробуй кожен дозволений варіант й одне невідоме слово.','For and, try both true, only one true, and both false. For or, try each allowed alternative and an unknown word.')
};
const thresholds={
 paragraphs:[T('Когда условия пересекаются, порядок меняет ответ. 95 больше и 50, и 90. Если первой стоит проверка >= 50, она сработает, и до >= 90 цепочка уже не дойдёт. Для награды за высокий результат сначала проверяем самый высокий порог.','Коли умови перетинаються, порядок змінює відповідь. 95 більше і 50, і 90. Якщо першою стоїть перевірка >= 50, вона спрацює, і до >= 90 ланцюжок не дійде. Для нагороди за високий результат спершу перевіряємо найвищий поріг.','Overlapping conditions make order important. 95 exceeds both 50 and 90. If >= 50 comes first, it matches and the chain never reaches >= 90. For threshold-based awards, check the highest threshold first.')],
 example:example(T('points = int(input())\nif points >= 90:\n    print("Золото")\nelif points >= 50:\n    print("Серебро")\nelse:\n    print("Бронза")','points = int(input())\nif points >= 90:\n    print("Золото")\nelif points >= 50:\n    print("Срібло")\nelse:\n    print("Бронза")','points = int(input())\nif points >= 90:\n    print("Gold")\nelif points >= 50:\n    print("Silver")\nelse:\n    print("Bronze")'),[
 T('Получаем количество очков.','Отримуємо кількість очок.','Read the point count.'),T('Сначала выделяем самые большие результаты.','Спершу виділяємо найбільші результати.','Identify the highest results first.'),T('Печатаем награду и пропускаем следующие ветки.','Друкуємо нагороду й пропускаємо наступні гілки.','Print the award and skip later branches.'),T('Раз мы дошли сюда, уже известно: points < 90. Теперь достаточно проверить нижнюю границу 50.','Якщо дійшли сюди, вже відомо: points < 90. Тепер достатньо перевірити нижню межу 50.','Reaching here already means points < 90. Only the lower bound of 50 needs checking.'),T('Эта награда покрывает значения 50–89.','Ця нагорода охоплює значення 50–89.','This award covers 50–89.'),T('После двух неудачных проверок остаются значения меньше 50.','Після двох хибних перевірок залишаються значення менші за 50.','After both checks are false, only values below 50 remain.'),T('Печатаем третью награду.','Друкуємо третю нагороду.','Print the third award.')],[
 ['49',T('Бронза','Бронза','Bronze'),T('Оба порога не достигнуты.','Обидва пороги не досягнуто.','Neither threshold is reached.')],['50',T('Серебро','Срібло','Silver'),T('Первый порог не достигнут, второй достигнут ровно.','Першого порогу не досягнуто, другого досягнуто рівно.','The first is not reached; the second is reached exactly.')],['90',T('Золото','Золото','Gold'),T('Первое условие уже верно.','Перша умова вже істинна.','The first condition is already true.')]]),
 rules:[T('Порог — значение, на котором меняется поведение. Проверяй каждый порог и соседние числа. >= и <= включают равенство; > и < исключают его.','Поріг — значення, на якому змінюється поведінка. Перевіряй кожен поріг і сусідні числа. >= та <= включають рівність; > та < виключають її.','A threshold is where behavior changes. Test each threshold and neighboring numbers. >= and <= include equality; > and < exclude it.'),T('Остаток от деления вычисляется через `%`: `13 % 4` равно 1, потому что 13 = 4 × 3 + 1. `12 % 4` равно 0. Проверка `number % 4 == 0` спрашивает, делится ли число на 4 без остатка.','Остачу від ділення обчислюють через `%`: `13 % 4` дорівнює 1, бо 13 = 4 × 3 + 1. `12 % 4` дорівнює 0. Перевірка `number % 4 == 0` запитує, чи ділиться число на 4 без остачі.','% calculates a remainder: `13 % 4` is 1 because 13 = 4 × 3 + 1. `12 % 4` is 0. `number % 4 == 0` asks whether the number divides exactly by 4.')],
 mistakes:[T('«Делится на первый И на второй» требует and. Or принимает число, которое делится только на один из них. Сначала отдельно проверь каждый остаток, потом выбери способ соединения.','«Ділиться на перше І на друге» вимагає and. Or приймає число, яке ділиться лише на одне з них. Спершу окремо перевір кожну остачу, потім обери спосіб поєднання.','“Divisible by the first AND the second” requires and. Or accepts a number divisible by only one. Check each remainder separately, then choose how to combine the checks.')],
 think:T('Для порогов составь маленькую таблицу «значение → ожидаемый ответ». Для делимости бери число, которое проходит только первую проверку, только вторую, обе и ни одну.','Для порогів склади маленьку таблицю «значення → очікувана відповідь». Для подільності візьми число, яке проходить лише першу перевірку, лише другу, обидві та жодну.','Make a small value-to-answer table for thresholds. For divisibility, test numbers passing only the first check, only the second, both, and neither.')
};
const ordering={
 paragraphs:[T('Программа не знает, какие данные разумны, пока мы не напишем проверку. Рост 301 подходит под >= 190, но в нашем примере допустим только диапазон 0–300. Поэтому сначала отклоняем неверный ввод, затем выбираем ответ для допустимого.','Програма не знає, які дані розумні, доки ми не напишемо перевірку. Зріст 301 підходить під >= 190, але в прикладі допустимий лише діапазон 0–300. Тому спершу відхиляємо неправильний ввід, далі обираємо відповідь для допустимого.','A program does not know which data are sensible until we add a check. Height 301 matches >= 190, but our example accepts only 0–300. Reject invalid input first, then decide what to do with valid input.')],
 example:example(T('height = int(input())\nif height < 0 or height > 300:\n    print("Проверь ввод")\nelif height >= 190:\n    print("Высокий рост")\nelse:\n    print("Обычный рост")','height = int(input())\nif height < 0 or height > 300:\n    print("Перевір ввід")\nelif height >= 190:\n    print("Високий зріст")\nelse:\n    print("Звичайний зріст")','height = int(input())\nif height < 0 or height > 300:\n    print("Check the input")\nelif height >= 190:\n    print("Tall")\nelse:\n    print("Regular height")'),[
 T('Получаем число. Int проверяет возможность преобразования, но сам не ограничивает допустимый диапазон.','Отримуємо число. Int перевіряє можливість перетворення, але сам не обмежує допустимий діапазон.','Read a number. Int converts it but does not enforce our allowed range.'),T('Вне диапазона означает: ниже нижнего края ИЛИ выше верхнего. Достаточно нарушить одну границу.','Поза діапазоном означає: нижче нижнього краю АБО вище верхнього. Достатньо порушити одну межу.','Outside means below the lower bound OR above the upper one. Either violation is enough.'),T('Сюда попадают только неверные значения.','Сюди потрапляють лише неправильні значення.','This handles invalid values only.'),T('До elif дошли — ввод уже допустим. Теперь выделяем высокие значения.','До elif дійшли — ввід уже допустимий. Тепер виділяємо високі значення.','Reaching elif means the input is valid. Now identify tall values.'),T('Первый подходящий допустимый ответ.','Перша відповідна допустима відповідь.','The first matching valid answer.'),T('Остались допустимые значения меньше 190.','Залишилися допустимі значення менші за 190.','The remaining values are valid and below 190.'),T('Выводим ответ для остальных допустимых значений.','Виводимо відповідь для решти допустимих значень.','Print the answer for the remaining valid values.')],[
 ['301',T('Проверь ввод','Перевір ввід','Check the input'),T('Первый if перехватывает неверное значение раньше общего порога.','Перший if перехоплює неправильне значення раніше загального порогу.','The first if catches invalid input before the broad threshold.')],['190',T('Высокий рост','Високий зріст','Tall'),T('Ввод допустим, порог включён.','Ввід допустимий, поріг включено.','The input is valid and equality is included.')],['189',T('Обычный рост','Звичайний зріст','Regular height'),T('Ни первая, ни вторая проверка не подошла.','Ні перша, ні друга перевірка не підійшла.','Neither the first nor the second check matches.')]]),
 rules:[T('Если особый случай входит в общий, поставь особый раньше. Например, точное совпадение с одним числом может оказаться внутри целого диапазона. После первой подходящей ветки elif уже не проверяется.','Якщо особливий випадок входить у загальний, постав його раніше. Наприклад, точний збіг з одним числом може міститися всередині діапазону. Після першої відповідної гілки elif уже не перевіряється.','If a special case is part of a general case, check the special case first. A single exact value may be inside a broader range. Later elif branches are skipped after a match.')],
 mistakes:[T('`height < 0 and height > 300` не проверяет «вне»: одно число не может одновременно быть ниже 0 и выше 300. Здесь нужен or. Внутри диапазона, наоборот, нужны обе границы с and.','`height < 0 and height > 300` не перевіряє «поза»: одне число не може водночас бути нижче 0 й вище 300. Тут потрібен or. Усередині діапазону, навпаки, потрібні обидві межі з and.','`height < 0 and height > 300` cannot detect outside values: one number cannot be both below 0 and above 300. Use or outside a range, and and for both inside bounds.')],
 think:T('Проверь невозможный ввод, каждый особый случай и обычный случай. Если ответ неверный, выясни, какая более ранняя ветка забрала значение.','Перевір неможливий ввід, кожен особливий випадок і звичайний випадок. Якщо відповідь неправильна, з’ясуй, яка попередня гілка забрала значення.','Test invalid input, every special case, and an ordinary case. If an answer is wrong, find which earlier branch intercepted that value.')
};
window.LEARNING_GUIDE={labels,basics,lessons:{first:{update:updateValue,if:firstIf,else:otherwise,elif:alternatives,nested,ternary:shortChoice},next:{warmup:alternatives,logic,boundaries:thresholds,nested,ordering,compact:shortChoice}}};
})();
